BEGIN;
INSERT INTO mission_bridge_permissions(key,description) VALUES('ministry_family.independent_support','Support ministry families across organizations') ON CONFLICT DO NOTHING;
INSERT INTO mission_bridge_role_permissions(role_key,permission_key) VALUES('safeguarding_officer','ministry_family.independent_support'),('platform_admin','ministry_family.independent_support') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS mission_bridge_ministry_family_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,owner_user_id TEXT NOT NULL,pseudonym TEXT NOT NULL,participant_type TEXT NOT NULL CHECK(participant_type IN('pastor','spouse','adult_child')),home_church_org_id TEXT,share_with_home_church BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,owner_user_id),CHECK(share_with_home_church=FALSE));
CREATE TABLE IF NOT EXISTS mission_bridge_ministry_family_access_denials(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),profile_id UUID NOT NULL REFERENCES mission_bridge_ministry_family_profiles(id),denied_relationship TEXT NOT NULL CHECK(denied_relationship IN('pastor_spouse','pastor_child','home_church_leader')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_cross_org_support_groups(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,title TEXT NOT NULL,host_org_id TEXT NOT NULL,cross_org_required BOOLEAN NOT NULL DEFAULT TRUE,confidentiality_policy TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',CHECK(cross_org_required=TRUE));
CREATE TABLE IF NOT EXISTS mission_bridge_family_rhythm_assessments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_ministry_family_profiles(id),role_pressure INTEGER CHECK(role_pressure BETWEEN 1 AND 5),family_absence INTEGER CHECK(family_absence BETWEEN 1 AND 5),public_expectation INTEGER CHECK(public_expectation BETWEEN 1 AND 5),ministry_exhaustion INTEGER CHECK(ministry_exhaustion BETWEEN 1 AND 5),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_ministry_rest_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_ministry_family_profiles(id),protected_time JSONB NOT NULL,boundary_actions JSONB NOT NULL,supervisor_outside_org TEXT,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS mission_bridge_ministry_family_referrals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_ministry_family_profiles(id),referral_type TEXT NOT NULL CHECK(referral_type IN('supervision','counseling','legal','medical')),outside_home_org BOOLEAN NOT NULL DEFAULT TRUE,status TEXT NOT NULL DEFAULT 'requested',CHECK(outside_home_org=TRUE));
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_ministry_family_profiles','mission_bridge_cross_org_support_groups','mission_bridge_family_rhythm_assessments','mission_bridge_ministry_rest_plans','mission_bridge_ministry_family_referrals'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
COMMIT;
